From: Martin Ferrand <martin.ferrand@edf.fr>
Date: Mon, 20 Nov 2023 13:03:15 +0100
Subject: [PATCH] Fix bug in rough wall functions (introduced in commit
 fd20e2d, 2023-11-14)


diff --git a/src/base/cs_boundary_conditions_set_coeffs_turb.c b/src/base/cs_boundary_conditions_set_coeffs_turb.c
index c0f242eb2..d0d84f7f2 100644
--- a/src/base/cs_boundary_conditions_set_coeffs_turb.c
+++ b/src/base/cs_boundary_conditions_set_coeffs_turb.c
@@ -2575,6 +2575,10 @@ cs_boundary_conditions_set_coeffs_turb(int        isvhb,
     if (boundary_ustar != NULL && icodcl_vel[f_id] == 5)
       bpro_ustar[f_id] = uet;

+    /* Rough wall: one velocity scale: set uk to uet */
+    if (cs_glob_wall_functions->iwallf <= 2 && icodcl_vel[f_id] == 6)
+      uk = uet;
+
     if(boundary_uk != NULL && icodcl_vel[f_id] == 5)
       bpro_uk[f_id] = uk;

@@ -2582,10 +2586,6 @@ cs_boundary_conditions_set_coeffs_turb(int        isvhb,
     if (f_yplus != NULL)
       yplbr[f_id] = yplus;

-    /* Rough wall : one velocity scale: set uk to uet */
-    if (cs_glob_wall_functions->iwallf < 2 && icodcl_vel[f_id] == 6)
-      uk = uet;
-
     uetmax  = cs_math_fmax(uet, uetmax);
     uetmin  = cs_math_fmin(uet, uetmin);
     ukmax   = cs_math_fmax(uk, ukmax);
@@ -4093,8 +4093,8 @@ cs_boundary_conditions_set_coeffs_turb(int        isvhb,
       cs_log_printf
         (CS_LOG_DEFAULT,
          _("\n"
-           "   ** Boundary conditions for smooth walls\n"
-           "      ------------------------------------\n\n"));
+           "   ** Boundary conditions for walls\n"
+           "      -----------------------------\n\n"));
       cs_log_separator(CS_LOG_DEFAULT);
       cs_log_printf
         (CS_LOG_DEFAULT,
